def analyze(g, out):
    H,W=len(g),len(g[0])
    oh,ow=len(out),len(out[0])
    vertical = any(len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=8 for c in range(W))
    if vertical:
        s=[c for c in range(W) if len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=8][0]
        A=[row[:s] for row in g]; B=[row[s+1:] for row in g]
    else:
        s=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=8][0]
        A=g[:s]; B=g[s+1:]
    # noise colors: least common per region
    from collections import Counter
    ca=Counter(x for row in A for x in row); cb=Counter(x for row in B for x in row)
    na=ca.most_common()[-1][0]; nb=cb.most_common()[-1][0]
    res={}
    if vertical:
        ANa={(r,c) for r in range(len(A)) for c in range(len(A[0])) if A[r][c]==na}
        BNb={(r,c) for r in range(len(B)) for c in range(len(B[0])) if B[r][c]==nb}
        threes={(r,c) for r in range(oh) for c in range(ow) if out[r][c]==3}
        res['inter']=ANa&BNb
        res['threes']=threes
        res['AminusB']=ANa-BNb
        # mirrored cell values in B
        res['mvals']={p:B[p[0]][p[1]] for p in ANa}
    else:
        ANa={(r,c) for r in range(len(A)) for c in range(len(A[0])) if A[r][c]==na}
        BNb={(r,c) for r in range(len(B)) for c in range(len(B[0])) if B[r][c]==nb}
        threes={(r,c) for r in range(oh) for c in range(ow) if out[r][c]==3}
        res['inter']={(r,c) for r,c in ANa if (r+len(B),c) in BNb}
        res['threes']=threes
        res['AminusB']={(r,c) for r,c in ANa if (r+len(B),c) not in BNb}
        res['mvals']={p:B[p[0]+len(B)][p[1]] for p in ANa}
    res['na'],res['nb']=na,nb
    return res
