def transform(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    def region_noise(cells):
        return Counter(x for r,c in cells).most_common()[-1][0]
    vert=[c for c in range(W) if len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=8]
    if vert:
        s=vert[0]
        A=[(r,c) for r in range(H) for c in range(s)]
        Bm=lambda r,c:(r,c); Bc=lambda r,c: g[r][s+1+c]
    else:
        s=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=8][0]
        A=[(r,c) for r in range(s) for c in range(W)]
        Bm=lambda r,c:(r,c); Bc=lambda r,c: g[s+1+r][c]
    na=region_noise(A)
    out=[[na]* (len(g[0]) if False else 0) for _ in range(0)]
    if vert:
        w=s; h=H
        out=[[na]*w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if g[r][c]==na and Bc(r,c)==na: out[r][c]=3
    else:
        w=W; h=len(A)
        out=[[na]*w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if g[r][c]==na and Bc(r,c)==na: out[r][c]=3
    return out
