import itertools
def get_regions(g):
    H,W=len(g),len(g[0])
    allc=Counter(x for row in g for x in row)
    def uniq(vals):
        return allc[vals[0]]==len(vals)
    vert=[c for c in range(W) if len(set(g[r][c] for r in range(H)))==1 and uniq([g[r][c] for r in range(H)])]
    if vert:
        s=vert[0]
        return ('v',s,g,H,s)   # A cols 0..s-1, B cols s+1..W-1
    sr=[r for r in range(H) if len(set(g[r]))==1 and uniq(g[r])][0]
    return ('h',sr,g,sr,W)
def check(name, inp, exp):
    t,s,g,_,w2=get_regions(inp)
    if t=='v':
        h,wa,wb=len(g),s,len(g[0])-s-1
        A_=g; B_=g
        def Bv(r,c,dy,dx):
            rr,cc=r+dy,c+s+1+dx
            return B_[rr][cc] if 0<=rr<h and 0<=cc<len(g[0]) else None
    else:
        h,wa,wb=s,len(g[0]),len(g)-s-1
        def Bv(r,c,dy,dx):
            rr,cc=r+s+1+dy,r if False else c+dx
            return B_[rr][cc] if 0<=rr<len(g) else None
        A_=g; B_=g
    na=Counter(g[r][c] for r in range(h) for c in range(wa)).most_common()[-1][0]
    th={(r,c) for r in range(h) for c in range(wa) if exp[r][c]==3}
