    for dy in (-2,-1,0,1,2):
        for dx in (-2,-1,0,1,2):
            m={(r,c) for r in range(h) for c in range(wa)
               if g[r][c]==na and Bv(r,c,dy,dx)==na}
            if m==th: res[(dy,dx)]=len(m)
    print(name,'na',na,'threes',len(th),'align matches:',res)
